#!/bin/bash
BASE_DIR="/mnt/d/lymphoma_project"   # <-- change this to your own path

OUTDIR="$BASE_DIR/WGBS/merged_raw"
TRIMDIR="$BASE_DIR/WGBS/merged_trimmed"
ALIGNDIR="$BASE_DIR/WGBS/merged_aligned"
METHYLDIR="$BASE_DIR/WGBS/merged_methylation"
GENOME="$BASE_DIR/reference/genome_fasta"
BISMARK="$BASE_DIR/Bismark/bismark"
METHEXT="$BASE_DIR/Bismark/bismark_methylation_extractor"
THREADS=8

mkdir -p $OUTDIR $TRIMDIR $ALIGNDIR $METHYLDIR

process_sample() {
    SAMPLE=$1
    shift
    RUNS=("$@")

    echo "==============================="
    echo "Processing sample: $SAMPLE"
    echo "Runs: ${RUNS[@]}"
    echo "==============================="

    SAMPLE_DIR="$OUTDIR/$SAMPLE"
    mkdir -p $SAMPLE_DIR

    # Step 1: Download all runs
    for RUN in "${RUNS[@]}"; do
        if [ ! -f "$SAMPLE_DIR/${RUN}.fastq" ]; then
            echo "Downloading: $RUN"
            prefetch $RUN --output-directory $SAMPLE_DIR
            fasterq-dump $RUN --outdir $SAMPLE_DIR --split-files
            rm -rf $SAMPLE_DIR/$RUN
        else
            echo "Already downloaded: $RUN"
        fi
    done

    # Step 2: Merge all fastq files
    echo "Merging fastq files for $SAMPLE..."
    cat $SAMPLE_DIR/*.fastq > $TRIMDIR/${SAMPLE}_merged.fastq
    echo "Merged!"

    # Step 3: Run fastp
    echo "Running fastp for $SAMPLE..."
    fastp \
        -i $TRIMDIR/${SAMPLE}_merged.fastq \
        -o $TRIMDIR/${SAMPLE}_trimmed.fastq \
        -h $TRIMDIR/${SAMPLE}_fastp.html \
        -j $TRIMDIR/${SAMPLE}_fastp.json \
        --thread $THREADS \
        --qualified_quality_phred 20 \
        --length_required 36
    echo "fastp done!"

    # Step 4: Run Bismark alignment
    echo "Running Bismark for $SAMPLE..."
    $BISMARK \
        --genome $GENOME \
        --parallel 1 \
        -o $ALIGNDIR \
        $TRIMDIR/${SAMPLE}_trimmed.fastq
    echo "Bismark done!"

    # Step 5: Methylation extraction
    BAM="$ALIGNDIR/${SAMPLE}_trimmed_bismark_bt2.bam"
    echo "Extracting methylation for $SAMPLE..."
    $METHEXT \
        --single-end \
        --comprehensive \
        --parallel 4 \
        --genome_folder $GENOME \
        --output $METHYLDIR \
        --bedGraph \
        --counts \
        $BAM
    echo "Methylation extraction done!"

    # Step 6: Cleanup raw files to free space
    echo "Cleaning up raw files for $SAMPLE..."
    rm -rf $SAMPLE_DIR
    rm -f $TRIMDIR/${SAMPLE}_merged.fastq
    rm -f $TRIMDIR/${SAMPLE}_trimmed.fastq
    echo "Cleanup done! Space freed!"

    echo "SAMPLE $SAMPLE COMPLETE!"
}
